export const FOIL_PACK_TICKETS = 10n;
/** Lower bound on lootBoxAmount in ETH purchases (LOOTBOX_MIN = 0.01 ether). */
// Contract minimum lootbox spend is 0.01 ether IN THE DEPLOYED CONTRACT'S
// SCALE — the testnet contracts are compiled /1M-scaled, so the on-chain
// minimum is 1e10 wei, not 1e16 (Phase 64 fix: sending the full-scale value
// silently overpaid 1M× into the buyer's afking credit).
export const LOOTBOX_MIN_WEI = ethers.parseEther('0.01') / ETH_DIVISOR;
/** Degenesis orders: at least 0.01 ETH in whole 0.0001 ETH units (DegenerusGameStorage DEGENESIS_MIN/UNIT). */
export const DEGENESIS_MIN_WEI = ethers.parseEther('0.01') / ETH_DIVISOR;
export const DEGENESIS_UNIT_WEI = ethers.parseEther('0.0001') / ETH_DIVISOR;
/** DEGENESIS_AMOUNT_MASK: an order is below 2^38 Degenesis units. */
export const DEGENESIS_MAX_WEI = ((1n << 38n) - 1n) * DEGENESIS_UNIT_WEI;

/**
 * Client copy of purchaseDegenesisBox's size and credit gates: null when the amount
 * would be accepted, else the reason. Never rounds; a non-unit amount is
 * rejected rather than silently trimmed.
 */
export function degenesisAmountError(amountWei, creditWei = null) {
  let amount;
  try { amount = BigInt(amountWei ?? 0n); } catch (_e) { return 'Enter a valid Degenesis box amount.'; }
  if (amount < DEGENESIS_MIN_WEI) return 'Minimum Degenesis box size is 0.01 ETH.';
  if (amount % DEGENESIS_UNIT_WEI !== 0n) return 'Degenesis boxes are sized in 0.0001 ETH steps.';
  if (amount > DEGENESIS_MAX_WEI) return 'That Degenesis box is larger than one order allows.';
  if (creditWei != null && amount > BigInt(creditWei)) return 'Degenesis credit is lower than that box size.';
  return null;
}

// ---------------------------------------------------------------------------
// Compact box orders (audit 4f4aa8377, LOOTBOX-COMPACT-ORDER-CLIENT-HANDOFF §1).
//
//   boxOrder = quantity | (kind << 7) | (customUnits << 9)       (30 bits)
//
// One kind per purchase (no mixed orders). quantity 1-100; kind 0/1/2/3 =
// small/medium/large/custom. Presets are 1x / 5x / 25x the routed ticket price
// and carry no units; a custom box carries its per-box value in LB_VALUE_UNIT
// (0.001 ETH mainnet; the testnet overlay's ÷1e6 makes it 1e9 wei, so the unit
// follows ETH_DIVISOR like every other ETH constant), 10-2,000,000 units. The
// contract reverts E() on anything else, so the encoder rejects it instead of
// flooring a user-entered value into a different box.
// ---------------------------------------------------------------------------

export const BOX_ORDER_MEDIUM_MULTIPLE = 5n;
export const BOX_ORDER_LARGE_MULTIPLE = 25n;
export const BOX_ORDER_MAX_BOXES = 100;
/** Kind names in on-chain order (the 2-bit kind field). */
export const BOX_ORDER_KINDS = Object.freeze(['small', 'medium', 'large', 'custom']);
/** Preset multiples of the routed ticket price, indexed by kind. */
export const BOX_ORDER_PRESET_MULTIPLES = Object.freeze([1n, BOX_ORDER_MEDIUM_MULTIPLE, BOX_ORDER_LARGE_MULTIPLE]);
/** BOX_CUSTOM_MIN_UNITS / LB_UNITS_MAX (unit-denominated, identical on testnet). */
export const BOX_CUSTOM_MIN_UNITS = 10n;
export const BOX_UNITS_MAX = 2_000_000n;
/** LB_VALUE_UNIT in the deployed contract's wei scale (1e15 mainnet, 1e9 testnet). */
export const BOX_VALUE_UNIT_WEI = (10n ** 15n) / ETH_DIVISOR;
/** Custom per-box bounds in deployed wei: 0.01 ETH and 2,000 ETH, scaled. */
export const BOX_CUSTOM_MIN_WEI = BOX_CUSTOM_MIN_UNITS * BOX_VALUE_UNIT_WEI;
export const BOX_CUSTOM_MAX_WEI = BOX_UNITS_MAX * BOX_VALUE_UNIT_WEI;
const BOX_ORDER_KIND_SHIFT = 7n;
const BOX_ORDER_UNITS_SHIFT = 9n;
const BOX_ORDER_HIGH_SHIFT = 30n;
const BOX_ORDER_QUANTITY_MASK = 0x7Fn;
const BOX_ORDER_KIND_MASK = 3n;
const BOX_ORDER_UNITS_MASK = 0x1FFFFFn;
const BOX_KIND_CUSTOM = 3;

function _boxOrderKind(kind) {
  const index = typeof kind === 'number' || typeof kind === 'bigint'
    ? Number(kind)
    : BOX_ORDER_KINDS.indexOf(String(kind ?? '').toLowerCase());
  if (!Number.isInteger(index) || index < 0 || index > 3) throw new RangeError('Choose a Luckbox size.');
  return index;
}

function _boxOrderQuantity(value) {
  const quantity = typeof value === 'bigint' ? Number(value) : Number(value ?? 0);
  if (!Number.isInteger(quantity) || quantity < 1 || quantity > BOX_ORDER_MAX_BOXES) {
    throw new RangeError(`Luckbox quantity must be a whole number from 1 to ${BOX_ORDER_MAX_BOXES}.`);
  }
  return quantity;
}

/**
 * Strictly convert a custom per-box wei value to LB_VALUE_UNIT units: a whole
 * 0.001 ETH (scaled), 0.01-2,000 ETH. Never floors.
 */
export function boxCustomUnitsFromWei(customWei) {
  let wei;
  try { wei = BigInt(customWei ?? 0n); }
  catch (_e) { throw new RangeError('Enter a valid custom box size.'); }
  if (wei % BOX_VALUE_UNIT_WEI !== 0n) {
    throw new RangeError('Custom box size must be a whole 0.001 ETH.');
  }
  const units = wei / BOX_VALUE_UNIT_WEI;
  if (units < BOX_CUSTOM_MIN_UNITS || units > BOX_UNITS_MAX) {
    throw new RangeError('Custom boxes must be 0.01-2,000 ETH each.');
  }
  return units;
}

/**
 * Encode one purchase's box leg: `{ kind, quantity, customWei }`. Kind is a
 * name ('small'|'medium'|'large'|'custom') or 0-3. Quantity 0 is "no box leg"
 * (0n: tickets/foil only); every other value must be a valid order.
 */
export function packBoxOrder({ kind, quantity = 0, customWei = 0n } = {}) {
  if (quantity === 0 || quantity === 0n || quantity == null) return 0n;
  const q = BigInt(_boxOrderQuantity(quantity));
  const k = _boxOrderKind(kind);
  let units = 0n;
  if (k === BOX_KIND_CUSTOM) units = boxCustomUnitsFromWei(customWei);
  else {
    let extra;
    try { extra = BigInt(customWei ?? 0n); } catch (_e) { extra = -1n; }
    if (extra !== 0n) throw new RangeError('A preset Luckbox carries no custom size.');
  }
  return q | (BigInt(k) << BOX_ORDER_KIND_SHIFT) | (units << BOX_ORDER_UNITS_SHIFT);
}

/**
 * Decode a packed order for quoting, tests, and receipt-side presentation.
 * Returns the raw fields plus per-kind presentation counts (exactly one lane is
 * nonzero for a valid order). Throws on an order the contract would reject.
 */
export function unpackBoxOrder(value = 0n) {
  let order = 0n;
  try { order = BigInt(value ?? 0n); }
  catch (_e) { throw new RangeError('Enter a valid packed box order.'); }
  if (order < 0n) throw new RangeError('Enter a valid packed box order.');
  const empty = { kind: null, kindIndex: null, quantity: 0, customUnits: 0n, customWei: 0n,
    small: 0, medium: 0, large: 0, customCount: 0, customSizeWei: 0n };
  if (order === 0n) return empty;
  const quantity = Number(order & BOX_ORDER_QUANTITY_MASK);
  const kindIndex = Number((order >> BOX_ORDER_KIND_SHIFT) & BOX_ORDER_KIND_MASK);
  const customUnits = (order >> BOX_ORDER_UNITS_SHIFT) & BOX_ORDER_UNITS_MASK;
  if (order >> BOX_ORDER_HIGH_SHIFT || quantity < 1 || quantity > BOX_ORDER_MAX_BOXES
    || (kindIndex === BOX_KIND_CUSTOM
      ? customUnits < BOX_CUSTOM_MIN_UNITS || customUnits > BOX_UNITS_MAX
      : customUnits !== 0n)) {
    throw new RangeError('Enter a valid packed box order.');
  }
  const kind = BOX_ORDER_KINDS[kindIndex];
  const customWei = customUnits * BOX_VALUE_UNIT_WEI;
  return {
    ...empty, kind, kindIndex, quantity, customUnits, customWei,
    ...(kind === 'custom' ? { customCount: quantity, customSizeWei: customWei } : { [kind]: quantity }),
  };
}

/** Decode a calldata/event box order. */
export function decodeBoxOrderForDeployment(value = 0n) {
  return unpackBoxOrder(value);
}

/** Per-box value in deployed wei for a decoded order at the given preset price. */
export function boxOrderPerBoxWei(priceWei, order) {
  if (!order?.kind) return 0n;
  if (order.kind === 'custom') return BigInt(order.customWei ?? 0n);
  let price = 0n;
  try { price = BigInt(priceWei ?? 0n); } catch (_e) { price = 0n; }
  if (price < 0n) price = 0n;
  return price * BOX_ORDER_PRESET_MULTIPLES[order.kindIndex ?? BOX_ORDER_KINDS.indexOf(order.kind)];
}

/** Quote an order: quantity x per-box value, exactly (no rounding of a purchase). */
export function boxOrderCostFromPriceWei(priceWei, value = 0n) {
  const order = unpackBoxOrder(value);
  return BigInt(order.quantity) * boxOrderPerBoxWei(priceWei, order);
}

function _boxOrderFromPurchaseArgs(args = {}) {
  if (args.boxOrder != null) {
    const packed = BigInt(args.boxOrder);
    // Decode and re-pack so high garbage bits, an over-cap total, and an
    // invalid custom lane fail before an RPC call instead of collapsing into
    // the contract's compact E() revert.
    const decoded = unpackBoxOrder(packed);
    if (packBoxOrder(decoded) !== packed) {
      throw new RangeError('Enter a valid packed box order.');
    }
    return packed;
  }
  if (args.boxSelection != null) return packBoxOrder(args.boxSelection);

  // Quantity-only call sites: a free ETH stake is one custom box (strict, never
  // floored); a bare count becomes that many Small (1x) presets.
  let legacyAmount = 0n;
  try { legacyAmount = BigInt(args.lootBoxAmountWei ?? 0n); }
  catch (_e) { throw new RangeError('Enter a valid custom box size.'); }
  if (legacyAmount > 0n) {
    return packBoxOrder({ kind: 'custom', quantity: 1, customWei: legacyAmount });
  }
  const legacyCount = Number(args.lootboxQuantity ?? 0);
  return legacyCount === 0 ? 0n : packBoxOrder({ kind: 'small', quantity: legacyCount });
}

// ---------------------------------------------------------------------------
// scaledTicketPriceWei — JS port of PriceLookupLib.priceForLevel (verified at
// contracts/libraries/PriceLookupLib.sol:21-41), divided by ETH_DIVISOR so the
// result is in the deployed contract's wei scale. The contract charges
// priceForLevel(_activeTicketLevel()) per whole ticket
// (DegenerusGameMintModule._purchaseCostInputs); callers get that level from
// app/active-level.js, NOT from a `jackpotPhase ? level : level + 1` shorthand.
// ---------------------------------------------------------------------------

export function scaledTicketPriceWei(targetLevel) {
  const lvl = Number(targetLevel);
  const ETHER = 10n ** 18n;
  let full;
  if (lvl < 5) full = ETHER / 100n;                 // 0.01 ether
  else if (lvl < 10) full = 2n * ETHER / 100n;      // 0.02 ether
  else {
    const cycleOffset = lvl % 100;
    if (cycleOffset === 0) {
      full = 24n * ETHER / 100n;                    // 0.24 ether milestone
    } else {
      const mult = (0x4333222111n >> (BigInt(Math.floor(cycleOffset / 10)) * 4n)) & 0xFn;
      full = 4n * ETHER / 100n * mult;              // 0.04 ether × decade tier
    }
  }
  return full / ETH_DIVISOR;
}

/**
 * Foil-pack cost at the target level, in the deployed contract's wei scale.
 * Contract: cost = FOIL_PACK_TICKETS × priceForLevel(lvl) — an ADDITIVE leg on
 * the purchase cost; claimable-first funding decides how much of that total is
 * recycled and how much must ride as msg.value.
 */
export function scaledFoilPackCostWei(targetLevel) {
  return FOIL_PACK_TICKETS * scaledTicketPriceWei(targetLevel);
}

/** Foil cost from the contract's exact routed buy-now ticket price. */
export function foilPackCostFromPriceWei(priceWei) {
  let price;
  try { price = BigInt(priceWei ?? 0n); } catch (_e) { return 0n; }
  return price > 0n ? FOIL_PACK_TICKETS * price : 0n;
}

