function _buildContract(signerOrProvider) {
  if (_contractFactory) return _contractFactory(signerOrProvider);
  return new ethers.Contract(CONTRACTS.GAME, walletAbi(GAME_ABI, abiGAME), signerOrProvider);
}

function _publicLootboxReadProvider() {
  if (!_rngQueueReadProvider && CHAIN.rpcUrl) {
    _rngQueueReadProvider = sharedReadProvider();  // C15: shared batched read stream
  }
  return _rngQueueReadProvider;
}

function _readBuyer() {
  // getActingAddress() → connected in 'self', viewed owner in 'operator', null
  // in 'view'/'combined' (read-only). purchase takes a buyer arg the contract
  // resolves via _resolvePlayer, so an approved operator buys on the owner's
  // behalf. The Phase 58 sendTx freshAddress guard still pins the
  // signer to the connected operator.
  const buyer = getActingAddress();
  if (!buyer) throw new Error('Wallet not connected.');
  return buyer;
}

/**
 * Exact buy-now quote from the deployed route. Unlike the API phase snapshot,
 * priceWei already accounts for a final sealed RNG window routing Level N
 * purchases into Level N+1.
 */
export async function readPurchaseQuote({ fresh = false } = {}) {
  try {
    let raw;
    if (_contractFactory) {
      const provider = getProvider();
      if (!provider) return null;
      const contract = _buildContract(provider);
      if (typeof contract.purchaseInfo_g1027 !== 'function') return null;
      raw = await contract.purchaseInfo_g1027();
    } else {
      raw = await readPurchaseInfo({ fresh });
    }
    const currentLevel = Number(raw?.currentLevel ?? raw?.lvl ?? raw?.[0]);
    const priceWei = BigInt(raw?.priceWei ?? raw?.[4] ?? 0n);
    if (!Number.isInteger(currentLevel) || currentLevel < 0 || priceWei <= 0n) return null;
    const quote = {
      currentLevel,
      inJackpotPhase: Boolean(raw?.inJackpotPhase ?? raw?.[1]),
      lastPurchaseDay: Boolean(raw?.lastPurchaseDay ?? raw?.lastPurchaseDay_ ?? raw?.[2]),
      rngLocked: Boolean(raw?.rngLocked ?? raw?.rngLocked_ ?? raw?.[3]),
      priceWei,
    };
    _purchaseQuoteMeta.set(quote, { fresh: Boolean(fresh), readAt: Date.now() });
    return quote;
  } catch (_e) {
    return null;
  }
}

function _recentFreshPurchaseQuote(value) {
  if (!value || typeof value !== 'object') return null;
  const meta = _purchaseQuoteMeta.get(value);
  return meta?.fresh === true && Date.now() - meta.readAt <= 5_000 ? value : null;
}

/** Storage position of centuryBonusUsed[walletId] in the deployed GAME. */
export async function centuryBonusUsedStorageSlot(walletId) {
  const id = Number(walletId);
  if (!Number.isSafeInteger(id) || id <= 0) return null;
  return ethers.keccak256(ethers.AbiCoder.defaultAbiCoder().encode(
    ['uint32', 'uint256'], [id, await _gameSlot('centuryBonusUsed')],
  ));
}

/** Decode `(level << 224) | used`; an older stamp means a fresh allowance. */
export function decodeCenturyBonusUsed(packedValue, targetLevel) {
  let packed;
  let level;
  try {
    packed = BigInt(packedValue ?? 0n);
    level = BigInt(targetLevel);
  } catch (_e) {
    return null;
  }
  if (level <= 0n) return null;
  return (packed >> 224n) === level ? packed & CENTURY_BONUS_USED_MASK : 0n;
}

/**
 * Read the player's already-consumed x00 allowance at one chain head.
 * Returns purchase units (400 = one ticket), matching the mint module.
 */
export async function readCenturyBonusUsed({ player, targetLevel, provider = null } = {}) {
  const level = Number(targetLevel);
  if (!Number.isInteger(level) || level <= 0 || level % 100 !== 0) return null;
  const reader = provider || _publicLootboxReadProvider() || getProvider();
  if (!reader || !CONTRACTS.GAME) return null;
  const walletId = await readWalletId(player, { provider: reader });
  if (walletId === 0) return 0n;
  const slot = await centuryBonusUsedStorageSlot(walletId);
  if (!slot) return null;
  let blockNumber = null;
  try {
    const head = Number(await reader.getBlockNumber?.());
    if (Number.isInteger(head) && head >= 0) blockNumber = head;
  } catch (_e) { /* an unpinned latest read is still useful */ }
  const packed = await _readGameStorage(reader, slot, blockNumber);
  return decodeCenturyBonusUsed(packed, level);
}

/**
 * Ask the deployed purchase route whether the acting buyer can add a foil pack
 * right now. A zero-value DirectEth probe is deliberately unaffordable: the
 * foil module reaches its PAYMENT stage only after all availability, liveness,
 * routing, and one-per-level checks have passed, so a shortfall revert there is
 * proof the route itself is open.
 *
 * Since audit c19a1088 that shortfall surfaces as the shared `Insolvent()` — the
 * canonical waterfall's revert — rather than the deleted `DirectEthInsufficient()`.
 * DirectEth skips the claimable tier, so a buyer with no prepaid AFKing lands on
 * Insolvent; a buyer holding enough AFKing instead SUCCEEDS the static call and is
 * caught by the success path above (the staticCall commits nothing either way).
 *
 * Success is accepted as well for forward compatibility with a zero-priced
 * deployment. Every other revert (including FoilAlreadyBought, StaleAdvance,
 * GameOver/liveness, and authorization failures) fails closed.
 *
 * Detailed form used by UI that needs to distinguish a permanent ownership
 * rejection from a temporary liveness/RPC miss. The boolean wrapper below
 * intentionally keeps its original fail-closed contract.
 *
 * @param {{buyer?: string}} [args]
 * @returns {Promise<{available: boolean, definitive: boolean, code: string}>}
 */
export async function probeFoilPackAvailabilityState({ buyer } = {}) {
  const buyerArg = buyer ?? getActingAddress();
  if (!buyerArg) return { available: false, definitive: false, code: 'NO_BUYER' };
  try {
    // This is an eth_call that deliberately expects an Insolvent revert as its
    // positive availability signal. Sending it through BrowserProvider makes
    // MetaMask report every caught probe as an "Internal JSON-RPC error" in the
    // page console. Use the shared public reader and explicitly preserve the
    // connected operator as msg.sender; in self mode that is the buyer.
    const caller = get('connected.address') ?? buyerArg;
    const provider = _publicLootboxReadProvider()
      || permissionlessReadProvider(getProvider());
    if (!provider) return { available: false, definitive: false, code: 'NO_PROVIDER' };
    const contract = _buildContract(provider);
    await contract.purchaseOrderFor.staticCall(
      await accountArg(buyerArg),
      0n,
      0n,
      ethers.ZeroHash,
      MINT_PAYMENT_KIND_DIRECT_ETH,
      true,
      { value: 0n, from: caller },
    );
    return { available: true, definitive: true, code: 'AVAILABLE' };
  } catch (error) {
    const decoded = decodeRevertReason(error);
    const rawName = typeof error?.revert?.name === 'string' ? error.revert.name : null;
    const code = decoded.code === 'UNKNOWN' && rawName ? rawName : decoded.code;
    if (code === 'Insolvent') {
      return { available: true, definitive: true, code };
    }
    // Ownership and authorization cannot heal on another poll for this exact
    // buyer/level. StaleAdvance and unknown transport/provider failures can.
    const definitive = code === 'FoilAlreadyBought'
      || code === 'NotApproved'
      || code === 'GameOver';
    return { available: false, definitive, code };
  }
}

/** Boolean, fail-closed compatibility wrapper. */
export async function probeFoilPackAvailability(args = {}) {
  return Boolean((await probeFoilPackAvailabilityState(args)).available);
}

function _structuredRevertError(error, context) {
  const decoded = decodeRevertReason(error);
  // A failed wallet/RPC check is not necessarily a contract revert. Preserve
  // its sanitized explanation instead of hiding it behind UNKNOWN's message.
  const userMessage = decoded.code === 'UNKNOWN'
    ? compactUiError(error)
    : decoded.userMessage || `Failed: ${context}`;
  const wrapped = new Error(userMessage);
  wrapped.code = decoded.code;
  wrapped.userMessage = userMessage;
  wrapped.recoveryAction = decoded.recoveryAction;
  wrapped.cause = error;
  return wrapped;
}

/** purchaseDegenesisBox reverts the compact E() for a closed sale, short credit or a bad size. */
function _structuredDegenesisRevertError(error, context) {
  const wrapped = _structuredRevertError(error, context);
  if (wrapped.code !== 'E') return wrapped;
  wrapped.code = 'DegenesisUnavailable';
  wrapped.userMessage = 'Degenesis box not accepted. The sale may be closed, or your credit changed.';
  wrapped.recoveryAction = 'Refresh your credit and try again.';
  wrapped.message = wrapped.userMessage;
  return wrapped;
}

// ---------------------------------------------------------------------------
// purchaseEth — purchaseOrderFor() with claimable-first funding for the
// ETH-denominated ticket/lootbox/foil combo. CONTEXT D-01 step 1 + D-04 wave 2.
//
// UNITS. The contract parameter is `entryQuantityScaled` (DegenerusGame.sol:703):
// "Purchase units (400 = 4*QTY_SCALE = one whole ticket = 4 entries)". So a whole
// TICKET is 400 units and one ENTRY is 100. Multiplying a ticket count by 100
// therefore buys a QUARTER of what it says, and — because the cost the contract
// charges is `priceWei * entryQuantityScaled / (4 * QTY_SCALE)` — pays four
// times over for it, with the excess credited silently to the payer's afking
// balance rather than refunded. Everything below is in whole TICKETS, converted
// once in entriesScaledFromTickets.
// ---------------------------------------------------------------------------


/** One entry is a quarter ticket; the contract's finest unit. */
export const ENTRIES_PER_TICKET = 4;

/**
 * Whole (or fractional) tickets → the contract's `entryQuantityScaled`.
 * Snaps to the nearest whole ENTRY, which is as fine as the chain goes: 0.25
 * tickets = 1 entry = 100 units.
 *
 * @param {number} tickets
 * @returns {bigint} purchase units (400 per whole ticket)
 */
export function entriesScaledFromTickets(tickets) {
  const t = Number(tickets);
  if (!Number.isFinite(t) || t <= 0) return 0n;
  return BigInt(Math.round(t * ENTRIES_PER_TICKET)) * 100n;
}

/**
 * What the contract will charge for `tickets`, exactly:
 * `priceWei * entryQuantityScaled / (4 * QTY_SCALE)` in integer arithmetic.
 * Overpaying is not refunded (it lands in afking), so this must match.
 *
 * @param {bigint} priceWei whole-ticket price at the target level
 * @param {number} tickets
 * @returns {bigint}
 */
export function ticketCostFromTickets(priceWei, tickets) {
  return (BigInt(priceWei) * entriesScaledFromTickets(tickets)) / 400n;
}

/**
 * Split a purchase so claimable winnings are consumed before wallet ETH.
 *
 * `claimableWinningsOf` returns the raw balance, including the contract's
 * permanent 1-wei sentinel. Combined payments consume fresh ETH first
 * on-chain, so sending only the shortfall makes the resulting split
 * claimable-first: the exact remainder must come from claimable.
 *
 * @param {bigint} totalCostWei
 * @param {bigint} rawClaimableWei
 * @returns {{payKind:number, msgValueWei:bigint, claimableUsedWei:bigint,
 *            totalCostWei:bigint}}
 */
export function claimableFirstPayment(totalCostWei, rawClaimableWei = 0n) {
  let total = 0n;
  let raw = 0n;
  try { total = BigInt(totalCostWei); } catch (_e) { total = 0n; }
  try { raw = BigInt(rawClaimableWei); } catch (_e) { raw = 0n; }
  if (total < 0n) total = 0n;
  if (raw < 0n) raw = 0n;

  const spendable = raw > 1n ? raw - 1n : 0n;
  const claimableUsedWei = spendable < total ? spendable : total;
  const msgValueWei = total - claimableUsedWei;
  const payKind = claimableUsedWei === 0n
    ? MINT_PAYMENT_KIND_DIRECT_ETH
    : msgValueWei === 0n
      ? MINT_PAYMENT_KIND_CLAIMABLE
      : MINT_PAYMENT_KIND_COMBINED;

  return { payKind, msgValueWei, claimableUsedWei, totalCostWei: total };
}

export function purchaseFundingPayment(
  totalCostWei,
  rawClaimableWei = 0n,
  rawAfkingWei = 0n,
  { useClaimable = true, useAfking = false } = {},
) {
  const base = claimableFirstPayment(totalCostWei, useClaimable ? rawClaimableWei : 0n);
  let afking = 0n;
  try { afking = BigInt(rawAfkingWei ?? 0); } catch (_e) { afking = 0n; }
  if (afking < 0n || !useAfking) afking = 0n;
  const afkingUsedWei = afking < base.msgValueWei ? afking : base.msgValueWei;
  return {
    ...base,
    msgValueWei: base.msgValueWei - afkingUsedWei,
    afkingUsedWei,
  };
}

async function _purchaseFundingFor(
  contract,
  buyer,
  totalCostWei,
  {
    useClaimable = true,
    useAfking = false,
  } = {},
) {
  if (!contract) {
    return purchaseFundingPayment(totalCostWei, 0n, 0n, { useClaimable, useAfking });
  }
  const reads = await Promise.allSettled([
    useClaimable && typeof contract.claimableWinningsOf === 'function'
      ? contract.claimableWinningsOf(buyer) : 0n,
    useAfking && typeof contract.afkingFundingOf === 'function'
      ? contract.afkingFundingOf(buyer) : 0n,
  ]);
  const claimable = reads[0].status === 'fulfilled' ? reads[0].value : 0n;
  const afking = reads[1].status === 'fulfilled' ? reads[1].value : 0n;
  // A read failure must not disable purchases. The unknown source simply
  // falls back to fresh ETH; the contract enforces the payment at execution.
  return purchaseFundingPayment(totalCostWei, claimable, afking, {
    useClaimable,
    useAfking,
  });
}

function _purchaseWalletFundingError(payment, { balanceWei = null, requiredWei = null } = {}) {
  let walletValueWei = 0n;
  let afkingUsedWei = 0n;
  let claimableUsedWei = 0n;
  try { walletValueWei = BigInt(payment?.msgValueWei ?? 0n); } catch (_e) { /* keep zero */ }
  try { afkingUsedWei = BigInt(payment?.afkingUsedWei ?? 0n); } catch (_e) { /* keep zero */ }
  try { claimableUsedWei = BigInt(payment?.claimableUsedWei ?? 0n); } catch (_e) { /* keep zero */ }

  const usesAfking = afkingUsedWei > 0n;
  const usesClaimable = claimableUsedWei > 0n;
  const internalLabel = usesAfking && usesClaimable
    ? 'AFKing and claimable funds'
    : usesAfking ? 'AFKing funding' : usesClaimable ? 'Claimable funds' : null;
  const gasOnly = walletValueWei === 0n;
  const userMessage = internalLabel
    ? gasOnly
      ? `With ${internalLabel} applied, your wallet still needs more ETH for network gas.`
      : `With ${internalLabel} applied, your wallet needs more ETH for the rest of the purchase and network gas.`
    : "This wallet doesn't have enough ETH for the transaction and gas.";
  const error = new Error(userMessage);
  error.name = 'PurchaseFundingError';
  error.code = 'InsufficientWalletFunds';
  error.userMessage = userMessage;
  error.recoveryAction = 'Add ETH to the connected wallet and try again.';
  error.balanceWei = balanceWei;
  error.requiredWei = requiredWei;
  return error;
}

async function _purchaseWalletBalance(provider, payer) {
  if (typeof provider?.getBalance !== 'function') return null;
  let address;
  try { address = typeof payer === 'string' ? payer : await payer?.getAddress?.(); }
  catch (_e) { return null; }
  if (!address) return null;
  try {
    return BigInt(await provider.getBalance(address, 'pending'));
  } catch (_pendingError) {
    try { return BigInt(await provider.getBalance(address)); }
    catch (_latestError) { return null; }
  }
}

/** Check native affordability against the same fixed gas ceiling used at send. */
async function _assertPurchaseWalletBudget({
  provider,
  payment,
  balanceWei,
  includeGas = false,
}) {
  const internalFundingWei = BigInt(payment?.claimableUsedWei ?? 0n)
    + BigInt(payment?.afkingUsedWei ?? 0n);
  if (internalFundingWei <= 0n) return null;

  const walletValueWei = BigInt(payment?.msgValueWei ?? 0n);
  // Equality is also unaffordable: it leaves no native ETH for a non-zero fee.
  if (balanceWei != null && balanceWei <= walletValueWei) {
    throw _purchaseWalletFundingError(payment, {
      balanceWei,
      requiredWei: walletValueWei + 1n,
    });
  }
  if (!includeGas) return null;
  const gasLimit = DEFAULT_TRANSACTION_GAS_LIMIT;
  let feeData;
  try { feeData = await transactionFeeData(provider); }
  catch (_e) { return { gasLimit, balanceWei, requiredWei: null, hasWideMargin: false }; }

  let feePerGas;
  try {
    feePerGas = BigInt(
      feeData?.maxFeePerGas ?? feeData?.gasPrice ?? 0n,
    );
  } catch (_e) {
    return { gasLimit, balanceWei, requiredWei: null, hasWideMargin: false };
  }
  if (feePerGas <= 0n) {
    return { gasLimit, balanceWei, requiredWei: null, hasWideMargin: false };
  }

  const requiredWei = walletValueWei + gasLimit * feePerGas;
  if (balanceWei != null && balanceWei < requiredWei) {
    throw _purchaseWalletFundingError(payment, { balanceWei, requiredWei });
  }
  return {
    gasLimit,
    balanceWei,
    requiredWei,
    // Only overrule a later wallet "insufficient" response when the public
    // quote shows ample room, not when the account merely clears the estimate.
    hasWideMargin: balanceWei != null && balanceWei >= requiredWei * 2n,
  };
}

function _purchaseWalletQuoteError(error) {
  const userMessage = 'Your wallet rejected a valid gas quote. Reconnect the wallet and try again.';
  const wrapped = new Error(userMessage);
  wrapped.name = 'PurchaseWalletQuoteError';
  wrapped.code = 'WalletGasQuoteRejected';
  wrapped.userMessage = userMessage;
  wrapped.recoveryAction = 'Refresh or reconnect the wallet, then retry the purchase.';
  wrapped.cause = error;
  return wrapped;
}

/**
 * @param {{ticketQuantity: number, boxOrder?: bigint, boxSelection?: object,
 *          boxCostWei?: bigint, lootboxQuantity?: number, lootBoxAmountWei?: bigint,
 *          affiliateCode?: string, ticketCostWei?: bigint,
 *          foil?: boolean, foilCostWei?: bigint,
 *          preferClaimable?: boolean, useAfking?: boolean,
 *          purchaseQuote?: object,
 *          onSubmitted?: function(import('ethers').TransactionResponse): void}} args
 *   ticketCostWei — scaled per-purchase ticket cost (scaledTicketPriceWei(target) ×
 *   quantity), computed by the panel from /game/state level + phase. It is part
 *   of the exact total; claimableFirstPayment decides the wallet shortfall.
 *   foil — buy the level's foil pack as an additive leg (one per player per
 *   level; contract reverts FoilAlreadyBought on a repeat). foilCostWei is NOT
 *   derived here — the panel passes scaledFoilPackCostWei(target) computed from
 *   the same fresh /game/state read as the ticket price, so both legs price
 *   against one snapshot.
 * @returns {Promise<{receipt: import('ethers').TransactionReceipt,
 *                    contract: import('ethers').Contract,
 *                    payment: {payKind:number,msgValueWei:bigint,
 *                              claimableUsedWei:bigint,totalCostWei:bigint}}>}
 */
const pendingFoilPurchases = new Set();

export async function purchaseEth(args) {
  if (!args.foil) return _purchaseEth(args);
  const key = `degenerus:foil-purchase:${CHAIN.id}:${CONTRACTS.GAME}:${_readBuyer()}`.toLowerCase();
  const pendingError = () => new Error('A foil pack purchase is already pending for this wallet.');
  // The panel's busy flag protects one instance. Protect the shared write
  // path too, including separate tabs: both funding reads can finish before the
  // first purchase mines, but only one foil can succeed for the level.
  if (pendingFoilPurchases.has(key)) throw pendingError();
  pendingFoilPurchases.add(key);
  try {
    if (globalThis.navigator?.locks?.request) {
      return await navigator.locks.request(key, { ifAvailable: true }, async lock => {
        if (!lock) throw pendingError();
        return _purchaseEth(args);
      });
    }
    return await _purchaseEth(args);
  } finally {
    pendingFoilPurchases.delete(key);
  }
}

async function _purchaseEth(args) {
  const buyer = _readBuyer();
  if (args.expectedBuyer && String(args.expectedBuyer).toLowerCase() !== String(buyer).toLowerCase()) {
    throw new Error('The selected account changed. Check the account and try again.');
  }
  const ticketQuantity = Number(args.ticketQuantity ?? 0);
  const boxOrder = _boxOrderFromPurchaseArgs(args);
  // Auto-read the chain-scoped affiliate when the packed-order purchase omits
  // an explicit code; affiliate plumbing remains independent of the builder UI.
  const affiliateCode = args.affiliateCode ?? readAffiliateCode(CHAIN.id, buyer);
  // purchaseInfo_g1027() is authoritative at click time. In the final sealed RNG
  // window the API can still say Level N while purchaseOrderFor() already routes to
  // Level N+1; preset box tiers and foils both derive from this routed price.
  const purchaseQuote = ticketQuantity > 0 || boxOrder > 0n || args.foil
    ? _recentFreshPurchaseQuote(args.purchaseQuote)
      || await readPurchaseQuote({ fresh: true })
    : null;
  const quotedPriceWei = purchaseQuote?.priceWei ?? 0n;
  let boxCostWei = 0n;
  if (boxOrder > 0n) {
    if (quotedPriceWei > 0n) {
      // Re-price presets from the click-time contract quote. A rendered form
      // quote may have crossed a routed-level boundary before the wallet opens.
      boxCostWei = boxOrderCostFromPriceWei(quotedPriceWei, boxOrder);
    } else if (args.boxCostWei != null) {
      try { boxCostWei = BigInt(args.boxCostWei); }
      catch (_e) { throw new Error('Enter a valid box order cost.'); }
    } else {
      // Presets use the routed ticket price. When an older test/degraded
      // provider cannot expose purchaseInfo_g1027(), the protocol's minimum ticket
      // price is the conservative compatibility fallback; custom orders are
      // fully priced from their packed size either way.
      const boxPriceWei = quotedPriceWei > 0n ? quotedPriceWei : LOOTBOX_MIN_WEI;
      boxCostWei = boxOrderCostFromPriceWei(boxPriceWei, boxOrder);
    }
    if (boxCostWei <= 0n) throw new Error('Box order cost is unavailable.');
  }
  if (args.expectedTicketPriceWei != null
    && quotedPriceWei !== BigInt(args.expectedTicketPriceWei)) {
    throw new Error('The ticket price changed. Check the updated price and click Buy One again.');
  }
  const ticketCostWei = quotedPriceWei > 0n && ticketQuantity > 0
    ? ticketCostFromTickets(quotedPriceWei, ticketQuantity)
    : BigInt(args.ticketCostWei ?? 0n);
  // Foil leg (additive): DegenerusGame._purchaseWithFoil caps fresh ETH at
  // tickets + boxes + FOIL_PACK_TICKETS × price and credits any excess to
  // afking, so msg.value must include the exact foil cost.
  const foil = Boolean(args.foil);
  const foilCostWei = foil
    ? quotedPriceWei > 0n
      ? foilPackCostFromPriceWei(quotedPriceWei)
      : BigInt(args.foilCostWei ?? 0n)
    : 0n;
  // Degenesis boxes are standalone (purchaseDegenesisBox): there is no combined selector.
  if (BigInt(args.degenesisAmountWei ?? 0n) !== 0n) {
    throw new Error('Buy the Degenesis box on its own, separately from tickets and Luckboxes.');
  }
  const totalCostWei = boxCostWei + ticketCostWei + foilCostWei;

  const provider = getProvider();
  const purchaseReader = provider ? permissionlessReadProvider(provider, { priority: 'interaction' }) : null;
  const purchaseReadContract = purchaseReader ? _buildContract(purchaseReader) : null;
  // Audit c19a1088 funds the foil leg through the SAME canonical waterfall as every
  // other purchase (claimable, then prepaid AFKing), so the old `&& !foil` carve-out
  // is obsolete: the module now taps AFKing principal instead of reverting on it.
  // Excluding AFKing here would inflate msg.value and make the buyer overpay from the
  // wallet for funds the contract would have drawn. Funding falls back to fresh ETH if the balance
  // reads fail, so a stale read cannot brick the purchase.
  const useAfkingForPurchase = args.useAfking === true;
  const payment = await _purchaseFundingFor(
    purchaseReadContract,
    buyer,
    totalCostWei,
    {
      useClaimable: args.preferClaimable !== false,
      useAfking: useAfkingForPurchase,
    },
  );

  // AFKing/claimable balances can cover the protocol value while the native
  // wallet is still too low to submit the transaction. The connected payer
  // covers gas even in operator mode. sendTx revalidates this account before
  // sending, so preparation needs no separate wallet-account round trip.
  const usesInternalFunding = BigInt(payment.claimableUsedWei ?? 0n) > 0n
    || BigInt(payment.afkingUsedWei ?? 0n) > 0n;
  const walletBalanceWei = provider && usesInternalFunding
    ? await _purchaseWalletBalance(purchaseReader || provider, get('connected.address'))
    : null;

  const entryQuantityScaled = entriesScaledFromTickets(ticketQuantity);
  const buyerId = await accountArg(buyer);
  let gasPlan = null;
  if (provider) {
    gasPlan = await _assertPurchaseWalletBudget({
      provider: purchaseReader || provider,
      payment,
      balanceWei: walletBalanceWei,
      includeGas: true,
    });
  }

  // Phase 58 chokepoint — closure form mandatory.
  let receipt;
  try {
    receipt = await sendTx(
      (s) => {
        if (args.expectedBuyer && String(getActingAddress() || '').toLowerCase() !== String(buyer).toLowerCase()) {
          throw new Error('The selected account changed. Check the account and try again.');
        }
        const c = _buildContract(s);
        return c.purchaseOrderFor(
          buyerId,
          entryQuantityScaled,
          boxOrder,
          affiliateCode,
          payment.payKind,
          foil,
          {
            value: payment.msgValueWei,
            ...(gasPlan?.gasLimit ? { gasLimit: gasPlan.gasLimit } : {}),
          }
        );
      },
      `${foil ? 'Buy foil pack' : ticketQuantity > 0 ? 'Buy tickets' : 'Buy boxes'} (${
        args.preferClaimable === false ? 'wallet ETH' : 'claimable first'
      })`,
      { onSubmitted: args.onSubmitted },
    );
  } catch (error) {
    if (gasPlan?.hasWideMargin
      && decodeRevertReason(error).code === 'InsufficientWalletFunds') {
      throw _purchaseWalletQuoteError(error);
    }
    throw error;
  }

  // Build a contract bound to the provider (signer-free) for log parsing.
  const contract = _buildContract(provider);
  return { receipt, contract, payment, boxOrder, boxCostWei };
}

// ---------------------------------------------------------------------------
// Degenesis boxes (DegenerusGameDegenesisModule.purchaseDegenesisBox). Every ETH-paid
// purchase (tickets, Luckboxes, foil, whale/deity passes, the AFKing cover-buy)
// earns 25% of its spend as credit until index 9 begins (_accrueDegenesisCredit);
// a box consumes credit 1:1. The write takes fresh ETH first, then the buyer's
// claimable, then AFKing funding; overpay is credited to the payer's AFKing.
// ---------------------------------------------------------------------------

/**
 * Remaining Degenesis credit for one player, or null when unreadable.
 * @param {{player?: string}} [args]
 * @returns {Promise<bigint|null>}
 */
export async function readDegenesisCredit({ player } = {}) {
  const owner = player || getActingAddress();
  if (!owner) return null;
  const provider = permissionlessReadProvider(getProvider());
  if (!provider) return null;
  const contract = _buildContract(provider);
  if (typeof contract.degenesisCreditOf !== 'function') return null;
  return BigInt(await contract.degenesisCreditOf(owner) ?? 0n);
}

/**
 * Buy one Degenesis box. The amount is re-checked against live credit before
 * send so a stale quote cannot overpay into AFKing.
 *
 * @param {{amountWei: bigint|string|number, player?: string, preferClaimable?: boolean,
 *          useAfking?: boolean,
 *          onSubmitted?: function(import('ethers').TransactionResponse): void}} args
 * @returns {Promise<{receipt,payment,creditWei:bigint}>}
 */
export async function purchaseDegenesisBox({
  amountWei,
  player,
  preferClaimable = true,
  useAfking = false,
  onSubmitted,
} = {}) {
  const buyer = player || _readBuyer();
  let requested;
  try { requested = BigInt(amountWei ?? 0n); }
  catch (_e) { throw new Error('Enter a valid Degenesis box amount.'); }
  const sizeError = degenesisAmountError(requested);
  if (sizeError) throw new Error(sizeError);

  const provider = getProvider();
  if (!provider) throw new Error('Wallet not connected.');
  const reader = permissionlessReadProvider(provider, { priority: 'interaction' });
  const contract = _buildContract(reader);
  const [creditWei, payment] = await Promise.all([
    readDegenesisCredit({ player: buyer }),
    _purchaseFundingFor(contract, buyer, requested, {
      useClaimable: preferClaimable !== false,
      useAfking: useAfking === true,
    }),
  ]);
  if (creditWei == null) throw new Error('The Degenesis sale is not available on this deployment.');
  const creditError = degenesisAmountError(requested, creditWei);
  if (creditError) throw new Error(creditError);

  const callArgs = [await accountArg(buyer), requested, { value: payment.msgValueWei }];

  let receipt;
  try {
    receipt = await sendTx(
      (s) => _buildContract(s).purchaseDegenesisBox(...callArgs),
      'Buy Degenesis box',
      { onSubmitted },
    );
  } catch (error) {
    throw _structuredDegenesisRevertError(error, 'send purchaseDegenesisBox');
  }
  return { receipt, payment, creditWei, orders: parseDegenesisBuyFromReceipt(receipt, _buildContract(provider)) };
}

/** DegenesisBuy receipt anchors (cohort day 1-7 + zero-based order index), in log order. */
export function parseDegenesisBuyFromReceipt(receipt, contract) {
  const out = [];
  if (!receipt || !Array.isArray(receipt.logs) || !contract?.interface) return out;
  for (const log of receipt.logs) {
    try {
      const parsed = walletReceiptLog(log, contract.interface);
      if (parsed?.name !== 'DegenesisBuy') continue;
      out.push({
        buyer: String(parsed.args.buyer ?? parsed.args[0]),
        degenesisDay: Number(parsed.args.degenesisDay ?? parsed.args[1]),
        orderIndex: Number(parsed.args.orderIndex ?? parsed.args[2]),
        amountWei: BigInt(parsed.args.amount ?? parsed.args[3]),
        secondsIntoDay: Number(parsed.args.secondsIntoDay ?? parsed.args[4]),
      });
    } catch (_e) { /* foreign log */ }
  }
  return out;
}

/**
 * Recover the box purchase legs sharing one RNG index from a mined transaction.
 * Purchase logs are the durable source of truth for which legs were bought. The current GAME deliberately exposes no per-player box amount.
 */
export async function readLootboxPurchaseReceipt({ transactionHash, player, lootboxIndex } = {}) {
  const hash = String(transactionHash || '');
  const owner = String(player || '').toLowerCase();
  let index;
  try { index = BigInt(lootboxIndex); } catch (_e) { return null; }
  if (!hash || !owner) return null;
  const connected = getProvider();
  const readers = _contractFactory
    ? [connected]
    : [_publicLootboxReadProvider(), connected];
  // Wallet RPCs occasionally omit an older receipt (notably after Firefox
  // reconnects). The public read RPC is authoritative enough for immutable
  // mined logs and lets Pending recover a box leg after a reload.
  for (const reader of [...new Set(readers.filter(Boolean))]) {
    if (typeof reader.getTransactionReceipt !== 'function') continue;
    try {
      const receipt = await readTransactionReceipt(hash, { provider: reader });
      await prepareWalletReceipt(receipt);
      if (!receipt || !Array.isArray(receipt.logs)) continue;
      const contract = _buildContract(reader);
      let hasLootboxLeg = false;
      let amountWei = 0n;
      for (const log of receipt.logs) {
        try {
          const parsed = walletReceiptLog(log, contract.interface);
          if (parsed?.name !== 'LootBoxBuy') continue;
          const buyer = String(parsed.args.buyer ?? parsed.args[0] ?? '').toLowerCase();
          const eventIndex = boxReference(parsed.args.index ?? parsed.args[1], parsed.args.position);
          if (buyer !== owner || eventIndex !== index) continue;
          amountWei += BigInt(parsed.args.amount ?? parsed.args[2] ?? 0);
          hasLootboxLeg = true;
        } catch (_e) { /* foreign log */ }
      }
      return { hasLootboxLeg, amountWei };
    } catch (_e) {
      // Try the public reader after an injected-wallet RPC miss.
    }
  }
  return null;
}

