// ---------------------------------------------------------------------------
// openLootBox — drives the in-order open sweep toward one tracked box. Audit
// 2525eb7fd removed openBox(player, index) and audit 18490c6fe removed the
// openBoxes(maxCount) valve: mineRun() is the only door to the chain's work.
// Its stages run in a fixed order (advance work first, then the afking and
// human box sweeps, each index's boxes and then its Degenerette bets) and pay
// the caller the miner bounty; every box credits its owner. A box behind a long
// queue, or behind earlier stages, may not be reached by one call, so the
// receipt block's own read answers `opened`.
// JS export keeps the openLootBox name — panel call sites are unchanged.
// ---------------------------------------------------------------------------

/**
 * @param {{lootboxIndex: bigint | number, player?: string}} args
 * @returns {Promise<{receipt, contract, opened: boolean | null}>} `opened` is
 *   false when the sweep stopped before this box, null when unreadable.
 */
export async function openLootBox(args) {
  // The tracked owner keeps a resolver click pinned to the item it rendered
  // even if the acting-account selector changes between paint and click. The
  // legacy acting-address default remains for direct panel callers.
  const player = args?.player || _readBuyer();
  const lootboxIndex = BigInt(args.lootboxIndex);

  const provider = getProvider();

  const receipt = await sendTx(
    async (s) => {
      const c = _buildContract(s);
      return c.mineRun(...mineFlipArgs(), { gasLimit: await mineFlipGasLimit(c) });
    },
    'Open luckbox'
  );

  let opened = null;
  try {
    const blockTag = receipt?.blockNumber == null ? 'latest' : Number(receipt.blockNumber);
    const state = await readLootboxBoxState({ player, lootboxIndex, blockTag });
    opened = state == null ? null : !state.pending;
  } catch (_e) { /* the caller's own probe and polling remain authoritative */ }

  const contract = _buildContract(provider);
  return { receipt, contract, opened };
}

/**
 * One player's box entry at one RNG index, straight from storage:
 * `{pending, worded, swept, rngLocked}`. `pending` is true while the box
 * order is still queued; `swept` once the in-order
 * frontier has passed the whole index. Null when no reader is available.
 */
export async function readLootboxBoxState({ player, lootboxIndex, blockTag = 'latest', provider = null } = {}) {
  if (_boxStateReader) return _boxStateReader({ player, lootboxIndex, blockTag });
  const reader = provider || permissionlessReadProvider(getProvider());
  if (!reader || !player || lootboxIndex == null || !CONTRACTS.GAME) return null;
  const entry = boxQueuePosition(BigInt(lootboxIndex));
  if (!entry) return null;
  const client = new ChainClient({ provider: reader });
  const s = await client.snapshot({ blockTag });
  const [pending, state, current] = await Promise.all([
    pendingBoxWord(s, 'boxQueue', entry.buffer, player, entry.position), s.word('GAME', 0), s.word('GAME', 3),
  ]);
  await s.verify();
  return { pending: pending !== 0n, swept: pending === 0n,
    worded: liveLootboxWord(state, entry.buffer, current) !== 0n,
    rngLocked: !!(state & (1n << 255n)) };
}

// ---------------------------------------------------------------------------
// parseLootboxIdxFromReceipt — extracts the queue index from LootBoxBuy.
